export enum DeliverabilityBand {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

export class EmailAccountEntity {
  smartleadInboxId: string;
  smartleadClientId: string;
  email: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  numberOfCampaignAssociated: number;
  warmupReputation: number | null;
  deliverabilityScore: number | null;
  deliverabilityBand: DeliverabilityBand;
  createdAt: string;
  updatedAt: string;

  constructor(partial: Partial<EmailAccountEntity>) {
    Object.assign(this, partial);
    this.domain = this.extractDomain(this.email);
    this.numberOfCampaignAssociated = this.campaignIds?.length || 0;
    this.deliverabilityScore = this.warmupReputation;
    this.deliverabilityBand = this.computeDeliverabilityBand(
      this.warmupReputation,
    );
    this.updatedAt = new Date().toISOString();
    if (!this.createdAt) {
      this.createdAt = this.updatedAt;
    }
  }

  private extractDomain(email: string): string {
    const parts = email.split('@');
    return parts.length === 2 ? parts[1].toLowerCase() : '';
  }

  private computeDeliverabilityBand(
    reputation: number | null,
  ): DeliverabilityBand {
    if (reputation === null || reputation === undefined) {
      return DeliverabilityBand.Unknown;
    }
    if (reputation === 100) {
      return DeliverabilityBand.High;
    }
    if (reputation >= 98) {
      return DeliverabilityBand.Medium;
    }
    if (reputation >= 95) {
      return DeliverabilityBand.Low;
    }
    return DeliverabilityBand.Burned;
  }

  addCampaignId(campaignId: string): void {
    if (!this.campaignIds.includes(campaignId)) {
      this.campaignIds.push(campaignId);
      this.numberOfCampaignAssociated = this.campaignIds.length;
      this.updatedAt = new Date().toISOString();
    }
  }

  removeCampaignId(campaignId: string): void {
    this.campaignIds = this.campaignIds.filter((id) => id !== campaignId);
    this.numberOfCampaignAssociated = this.campaignIds.length;
    this.updatedAt = new Date().toISOString();
  }

  updateWarmupReputation(reputation: number | null): void {
    this.warmupReputation = reputation;
    this.deliverabilityScore = reputation;
    this.deliverabilityBand = this.computeDeliverabilityBand(reputation);
    this.updatedAt = new Date().toISOString();
  }

  addTag(tag: string): void {
    if (!this.tags.includes(tag)) {
      this.tags.push(tag);
      this.updatedAt = new Date().toISOString();
    }
  }

  removeTag(tag: string): void {
    this.tags = this.tags.filter((t) => t !== tag);
    this.updatedAt = new Date().toISOString();
  }
}

