import { IsString, IsOptional, IsArray, IsNumber, Min, Max } from 'class-validator';
import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { DeliverabilityBand } from '../entities/email-account.entity';

export class EmailAccountDto {
  @ApiProperty({ description: 'Smartlead inbox ID (unique identifier)' })
  @IsString()
  smartleadInboxId: string;

  @ApiProperty({ description: 'Smartlead client ID' })
  @IsString()
  smartleadClientId: string;

  @ApiProperty({ description: 'Email address of the inbox' })
  @IsString()
  email: string;

  @ApiPropertyOptional({ description: 'Tags associated with the inbox' })
  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  tags?: string[];

  @ApiPropertyOptional({ description: 'Campaign IDs associated with the inbox' })
  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  campaignIds?: string[];
}

export class EmailAccountCreateDto {
  @ApiProperty({ description: 'Smartlead inbox ID (unique identifier)' })
  @IsString()
  smartleadInboxId: string;

  @ApiProperty({ description: 'Smartlead client ID' })
  @IsString()
  smartleadClientId: string;

  @ApiProperty({ description: 'Email address of the inbox' })
  @IsString()
  email: string;

  @ApiPropertyOptional({ description: 'Tags associated with the inbox' })
  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  tags?: string[];
}

export class EmailAccountUpdateDto {
  @ApiPropertyOptional({ description: 'Tags associated with the inbox' })
  @IsOptional()
  @IsArray()
  @IsString({ each: true })
  tags?: string[];
}

export class EmailAccountListDto {
  @ApiProperty({ description: 'Total number of emails to send in the campaign' })
  @IsNumber()
  @Min(1)
  totalNumberOfEmailsToSend: number;

  @ApiProperty({ description: 'Smartlead client ID' })
  @IsString()
  smartleadClientId: string;

  @ApiProperty({ description: 'Campaign ID' })
  @IsString()
  campaignId: string;

  @ApiPropertyOptional({ description: 'Number of days in the campaign', default: 10 })
  @IsOptional()
  @IsNumber()
  @Min(1)
  numberOfDaysInCampaign?: number;

  @ApiPropertyOptional({ description: 'Emails per inbox per day', default: 20 })
  @IsOptional()
  @IsNumber()
  @Min(1)
  emailsPerInboxPerDay?: number;
}

export class EmailAccountCampaignAssociationDto {
  @ApiProperty({ description: 'Array of Smartlead inbox IDs to associate with the campaign' })
  @IsArray()
