  emailAccountIds: string[];

  @ApiProperty({ description: 'Campaign ID to associate with' })
  @IsString()
  campaignId: string;
}

export class EmailAccountLookupDto {
  @ApiPropertyOptional({ description: 'Smartlead inbox ID' })
  @IsOptional()
  @IsString()
  smartleadInboxId?: string;

  @ApiPropertyOptional({ description: 'Email address' })
  @IsOptional()
  @IsString()
  email?: string;

  @ApiPropertyOptional({ description: 'Smartlead client ID' })
  @IsOptional()
  @IsString()
  smartleadClientId?: string;
}

export class EmailAccountPaginatedListDto {
  @ApiPropertyOptional({ description: 'Page number', default: 1 })
  @IsOptional()
  @IsNumber()
  @Min(1)
  page?: number = 1;

  @ApiPropertyOptional({ description: 'Page size', default: 20 })
  @IsOptional()
  @IsNumber()
  @Min(1)
  @Max(100)
  pageSize?: number = 20;

  @ApiPropertyOptional({ description: 'Smartlead client ID to filter by' })
  @IsOptional()
  @IsString()
