import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { DatastoreService } from '../datastore/datastore.service';
import { StoreDataDto } from '../datastore/dto/store.dto';
import { FindDataDto } from '../datastore/dto/find.dto';
import { documentType } from '../datastore/entites/documentType';
import {
  EmailAccountEntity,
  DeliverabilityBand,
} from './entities/email-account.entity';
import {
  EmailAccountCreateDto,
  EmailAccountUpdateDto,
  EmailAccountListDto,
  EmailAccountCampaignAssociationDto,
  EmailAccountLookupDto,
  EmailAccountPaginatedListDto,
  EmailAccountResponseDto,
  EmailAccountPaginatedResponseDto,
  BestEmailAccountsForCampaignDto,
  EmailAccountImportResultDto,
} from './dto/email-account.dto';
import { SmartleadService } from '../smartlead/smartlead.service';

const EMAILS_PER_INBOX_PER_DAY_DEFAULT = 20;
const CAMPAIGN_DAYS_DEFAULT = 10;

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);

  constructor(
    private readonly datastoreService: DatastoreService,
    private readonly smartleadService: SmartleadService,
  ) {}

  private toResponseDto(entity: EmailAccountEntity): EmailAccountResponseDto {
    return {
      smartleadInboxId: entity.smartleadInboxId,
      smartleadClientId: entity.smartleadClientId,
      email: entity.email,
      domain: entity.domain,
      tags: entity.tags,
      campaignIds: entity.campaignIds,
      numberOfCampaignAssociated: entity.numberOfCampaignAssociated,
      warmupReputation: entity.warmupReputation,
      deliverabilityScore: entity.deliverabilityScore,
      deliverabilityBand: entity.deliverabilityBand,
      createdAt: entity.createdAt,
      updatedAt: entity.updatedAt,
    };
  }

  async createEmailAccount(
    createDto: EmailAccountCreateDto,
  ): Promise<EmailAccountResponseDto> {
    this.logger.log(
      `Creating email account for inbox: ${createDto.smartleadInboxId}`,
    );

    const existing = await this.getEmailAccountById(createDto.smartleadInboxId);
    if (existing) {
      this.logger.log(
        `Email account already exists for inbox: ${createDto.smartleadInboxId}, updating`,
      );
      return this.updateEmailAccount(createDto.smartleadInboxId, {
        tags: createDto.tags,
      });
    }

    const hydrated = await this.hydrateFromSmartlead(
      createDto.smartleadInboxId,
      createDto.smartleadClientId,
    );
    if (!hydrated) {
      throw new NotFoundException(
        `Smartlead inbox ${createDto.smartleadInboxId} not found`,
      );
    }

    const entity = new EmailAccountEntity({
      ...hydrated,
      tags: createDto.tags || [],
      campaignIds: [],
    });

    await this.datastoreService.store(
      new StoreDataDto({
        data: entity,
        context: { documentType: documentType.EMAIL_ACCOUNT },
      }),
    );

    this.logger.log(`Created email account: ${entity.smartleadInboxId}`);
    return this.toResponseDto(entity);
  }

  private async hydrateFromSmartlead(
    smartleadInboxId: string,
    smartleadClientId: string,
  ): Promise<Partial<EmailAccountEntity> | null> {
    try {
      this.logger.log(
        `Fetching email account details from Smartlead for inbox: ${smartleadInboxId}`,
      );
      const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
      const res = await fetch(
        `https://server.smartlead.ai/api/v1/email-accounts/${smartleadInboxId}?api_key=${apiKey}`,
      );

      if (res.status === 404) {
        this.logger.warn(
          `Smartlead inbox not found: ${smartleadInboxId}`,
        );
        return null;
      }

      if (!res.ok) {
        this.logger.error(
          `Failed to fetch email account from Smartlead: ${res.status}`,
        );
        throw new InternalServerErrorException(
          'Failed to fetch email account from Smartlead',
        );
      }

      const data = await res.json();
      this.logger.log(
        `Got Smartlead email account data: ${JSON.stringify(data)}`,
      );

      const email = data.email || data.email_address;
      if (!email) {
        throw new InternalServerErrorException(
          'Email address not found in Smartlead response',
        );
      }

      const warmupReputation = data.warmup_reputation ?? data.reputation ?? null;
      const createdAt = data.created_at || data.createdAt || new Date().toISOString();

      return {
        smartleadInboxId,
        smartleadClientId,
        email,
        warmupReputation: warmupReputation !== null ? Number(warmupReputation) : null,
        createdAt,
        tags: [],
        campaignIds: [],
      };
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error(`Error hydrating from Smartlead: ${error}`);
      throw new InternalServerErrorException(
        'Failed to hydrate email account from Smartlead',
      );
    }
  }

  async getEmailAccountById(
    smartleadInboxId: string,
  ): Promise<EmailAccountResponseDto | null> {
    const result = await this.datastoreService.getById({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data) {
      return null;
    }

    const entity = new EmailAccountEntity(result.data);
    return this.toResponseDto(entity);
  }

  async getEmailAccountByEmail(
    email: string,
  ): Promise<EmailAccountResponseDto | null> {
    const result = await this.datastoreService.getByField({
      fieldKey: 'data.email',
      fieldValue: email.toLowerCase(),
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data || result.data.length === 0) {
      return null;
    }

    const entity = new EmailAccountEntity(result.data[0]);
    return this.toResponseDto(entity);
  }

  async getEmailAccountsByClientId(
    smartleadClientId: string,
  ): Promise<EmailAccountResponseDto[]> {
    const result = await this.datastoreService.getByField({
      fieldKey: 'data.smartleadClientId',
      fieldValue: smartleadClientId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data || result.data.length === 0) {
      return [];
    }

    return result.data
      .map((d) => new EmailAccountEntity(d))
      .map((e) => this.toResponseDto(e));
  }

  async listEmailAccounts(
    listDto: EmailAccountPaginatedListDto,
  ): Promise<EmailAccountPaginatedResponseDto> {
    const page = listDto.page || 1;
    const pageSize = listDto.pageSize || 20;

    const result = await this.datastoreService.getByField({
      fieldKey: listDto.smartleadClientId ? 'data.smartleadClientId' : 'data.smartleadInboxId',
      fieldValue: listDto.smartleadClientId || '',
      documentType: documentType.EMAIL_ACCOUNT,
      pagination: { page, pageSize },
    });

    const allAccounts = await this.getEmailAccountsByClientId(
      listDto.smartleadClientId || '',
    );

    const start = (page - 1) * pageSize;
    const end = start + pageSize;
    const paginatedData = allAccounts.slice(start, end);

    return {
      data: paginatedData,
      total: allAccounts.length,
      page,
      pageSize,
      totalPages: Math.ceil(allAccounts.length / pageSize),
    };
  }

  async updateEmailAccount(
    smartleadInboxId: string,
    updateDto: EmailAccountUpdateDto,
  ): Promise<EmailAccountResponseDto> {
    const existing = await this.getEmailAccountById(smartleadInboxId);
    if (!existing) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }

    const result = await this.datastoreService.getById({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    const entity = new EmailAccountEntity(result.data);
    if (updateDto.tags !== undefined) {
      entity.tags = updateDto.tags;
      entity.updatedAt = new Date().toISOString();
    }

    await this.datastoreService.store(
      new StoreDataDto({
        data: entity,
        context: { documentType: documentType.EMAIL_ACCOUNT },
      }),
    );

    this.logger.log(`Updated email account: ${smartleadInboxId}`);
    return this.toResponseDto(entity);
  }

  async deleteEmailAccount(
    smartleadInboxId: string,
  ): Promise<{ message: string }> {
    const existing = await this.getEmailAccountById(smartleadInboxId);
    if (!existing) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }

    await this.datastoreService.remove({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    this.logger.log(`Deleted email account: ${smartleadInboxId}`);
    return { message: 'Email account deleted successfully' };
  }

  async associateEmailAccountsWithCampaign(
    associationDto: EmailAccountCampaignAssociationDto,
  ): Promise<EmailAccountResponseDto[]> {
    const { emailAccountIds, campaignId } = associationDto;

    const uniqueInboxIds = [...new Set(emailAccountIds)];
    if (uniqueInboxIds.length !== emailAccountIds.length) {
      this.logger.log(
        `Duplicate inbox IDs in request, deduplicated from ${emailAccountIds.length} to ${uniqueInboxIds.length}`,
      );
    }

    const missingInboxes: string[] = [];
    const accountsToUpdate: EmailAccountEntity[] = [];

    for (const inboxId of uniqueInboxIds) {
      const result = await this.datastoreService.getById({
        id: inboxId,
        documentType: documentType.EMAIL_ACCOUNT,
      });

      if (!result?.data) {
        missingInboxes.push(inboxId);
        continue;
      }

      const entity = new EmailAccountEntity(result.data);
      entity.addCampaignId(campaignId);
      accountsToUpdate.push(entity);
    }

    if (missingInboxes.length > 0) {
      this.logger.error(
        `Missing inboxes in association request: ${missingInboxes.join(', ')}`,
      );
      throw new NotFoundException(
        `The following inbox IDs were not found: ${missingInboxes.join(', ')}`,
      );
    }

    for (const entity of accountsToUpdate) {
      await this.datastoreService.store(
        new StoreDataDto({
          data: entity,
          context: { documentType: documentType.EMAIL_ACCOUNT },
        }),
      );
    }

    this.logger.log(
      `Associated ${accountsToUpdate.length} email accounts with campaign: ${campaignId}`,
    );
    return accountsToUpdate.map((e) => this.toResponseDto(e));
  }

  async disassociateEmailAccountFromCampaign(
    smartleadInboxId: string,
    campaignId: string,
  ): Promise<EmailAccountResponseDto> {
    const result = await this.datastoreService.getById({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    if (!result?.data) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }

    const entity = new EmailAccountEntity(result.data);
    entity.removeCampaignId(campaignId);

    await this.datastoreService.store(
      new StoreDataDto({
        data: entity,
        context: { documentType: documentType.EMAIL_ACCOUNT },
      }),
    );

    this.logger.log(
      `Disassociated email account ${smartleadInboxId} from campaign: ${campaignId}`,
    );
    return this.toResponseDto(entity);
  }

  async getBestEmailAccountsForCampaign(
    listDto: EmailAccountListDto,
  ): Promise<BestEmailAccountsForCampaignDto> {
    const {
      smartleadClientId,
      campaignId,
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign = CAMPAIGN_DAYS_DEFAULT,
      emailsPerInboxPerDay = EMAILS_PER_INBOX_PER_DAY_DEFAULT,
    } = listDto;

    this.logger.log(
      `Finding best email accounts for campaign: ${campaignId}, client: ${smartleadClientId}`,
    );

    const requiredPoolSize = Math.floor(
      totalNumberOfEmailsToSend /
        numberOfDaysInCampaign /
        emailsPerInboxPerDay,
    );

    this.logger.log(
      `Required pool size: ${requiredPoolSize} (${totalNumberOfEmailsToSend} emails / ${numberOfDaysInCampaign} days / ${emailsPerInboxPerDay} emails per inbox per day)`,
    );

    const allAccounts = await this.getEmailAccountsByClientId(
      smartleadClientId,
    );

    if (allAccounts.length === 0) {
      this.logger.warn(
        `No email accounts found for client: ${smartleadClientId}`,
      );
      return {
        emailAccounts: [],
        requiredPoolSize,
        availableAccounts: 0,
      };
    }

    const accountsWithDomainCounts = this.computeDomainCounts(allAccounts);

    const sortedAccounts = accountsWithDomainCounts.sort((a, b) => {
      const scoreA = a.deliverabilityScore ?? -1;
      const scoreB = b.deliverabilityScore ?? -1;

      if (scoreB !== scoreA) {
        return scoreB - scoreA;
      }

      if (a.numberOfCampaignAssociated !== b.numberOfCampaignAssociated) {
        return a.numberOfCampaignAssociated - b.numberOfCampaignAssociated;
      }

      const domainCountA = a._domainCount || 0;
      const domainCountB = b._domainCount || 0;
      if (domainCountA !== domainCountB) {
        return domainCountA - domainCountB;
      }

      return (
        new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
      );
    });

    const selectedAccounts = sortedAccounts.slice(0, requiredPoolSize);

    this.logger.log(
      `Selected ${selectedAccounts.length} email accounts for campaign: ${campaignId}`,
    );

    return {
      emailAccounts: selectedAccounts.map((a) => this.toResponseDto(a)),
      requiredPoolSize,
      availableAccounts: allAccounts.length,
    };
  }

  private computeDomainCounts(
    accounts: EmailAccountResponseDto[],
  ): (EmailAccountResponseDto & { _domainCount: number })[] {
    const domainCounts = new Map<string, number>();

    for (const account of accounts) {
      const count = domainCounts.get(account.domain) || 0;
      domainCounts.set(account.domain, count + 1);
    }

    return accounts.map((account) => ({
      ...account,
      _domainCount: (domainCounts.get(account.domain) || 1) - 1,
    }));
  }

  async importEmailAccountsFromSmartlead(
    smartleadClientId: string,
  ): Promise<EmailAccountImportResultDto> {
    this.logger.log(
      `Importing email accounts from Smartlead for client: ${smartleadClientId}`,
    );

    try {
      const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
      const res = await fetch(
        `https://server.smartlead.ai/api/v1/email-accounts/?api_key=${apiKey}&client_id=${smartleadClientId}`,
      );

      if (!res.ok) {
        throw new InternalServerErrorException(
          `Failed to fetch email accounts from Smartlead: ${res.status}`,
        );
      }

      const data = await res.json();
      const smartleadAccounts = Array.isArray(data) ? data : data.email_accounts || [];

      this.logger.log(
        `Fetched ${smartleadAccounts.length} email accounts from Smartlead`,
      );

      const imported: EmailAccountResponseDto[] = [];
      const failed: string[] = [];

      for (const account of smartleadAccounts) {
        try {
          const inboxId = String(account.id || account.email_account_id);
          const email = account.email || account.email_address;

          if (!inboxId || !email) {
            failed.push(`${inboxId || 'unknown'}: missing id or email`);
            continue;
          }

          const existing = await this.getEmailAccountById(inboxId);
          if (existing) {
            const hydrated = await this.hydrateFromSmartlead(
              inboxId,
              smartleadClientId,
            );
            if (hydrated) {
              const result = await this.datastoreService.getById({
                id: inboxId,
                documentType: documentType.EMAIL_ACCOUNT,
              });
              const entity = new EmailAccountEntity(result.data);
              entity.updateWarmupReputation(hydrated.warmupReputation ?? null);
              await this.datastoreService.store(
                new StoreDataDto({
                  data: entity,
                  context: { documentType: documentType.EMAIL_ACCOUNT },
                }),
              );
              imported.push(this.toResponseDto(entity));
            }
            continue;
          }

          const created = await this.createEmailAccount({
            smartleadInboxId: inboxId,
            smartleadClientId,
            email,
          });
          imported.push(created);
        } catch (error) {
          this.logger.error(
            `Failed to import email account: ${error}`,
          );
          failed.push(`${account.id || account.email || 'unknown'}: ${error.message}`);
        }
      }

      return {
        imported,
        failed,
        totalFetched: smartleadAccounts.length,
      };
    } catch (error) {
      this.logger.error(`Error importing email accounts: ${error}`);
      throw new InternalServerErrorException(
        'Failed to import email accounts from Smartlead',
      );
    }
  }

  async syncWarmupReputation(
    smartleadClientId?: string,
  ): Promise<EmailAccountImportResultDto> {
    this.logger.log(`Syncing warmup reputation${smartleadClientId ? ` for client: ${smartleadClientId}` : ''}`);

    let accounts: EmailAccountResponseDto[];

    if (smartleadClientId) {
      accounts = await this.getEmailAccountsByClientId(smartleadClientId);
    } else {
      const result = await this.datastoreService.getByPattern({
        pattern: '*',
        documentType: documentType.EMAIL_ACCOUNT,
      });
      accounts = (result?.data || []).map((d) =>
        this.toResponseDto(new EmailAccountEntity(d)),
      );
    }

    const updated: EmailAccountResponseDto[] = [];
    const failed: string[] = [];

    for (const account of accounts) {
      try {
        const hydrated = await this.hydrateFromSmartlead(
          account.smartleadInboxId,
          account.smartleadClientId,
        );

        if (hydrated && hydrated.warmupReputation !== null) {
          const result = await this.datastoreService.getById({
            id: account.smartleadInboxId,
            documentType: documentType.EMAIL_ACCOUNT,
          });
          const entity = new EmailAccountEntity(result.data);
          entity.updateWarmupReputation(hydrated.warmupReputation);
          await this.datastoreService.store(
            new StoreDataDto({
              data: entity,
              context: { documentType: documentType.EMAIL_ACCOUNT },
            }),
          );
          updated.push(this.toResponseDto(entity));
        }
      } catch (error) {
        this.logger.error(
          `Failed to sync reputation for ${account.smartleadInboxId}: ${error}`,
        );
        failed.push(`${account.smartleadInboxId}: ${error.message}`);
      }
    }

    return {
      imported: updated,
      failed,
      totalFetched: accounts.length,
    };
  }
}

