import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiParam, ApiQuery } from '@nestjs/swagger';
import { EmailinfraService } from './emailinfra.service';
import {
  EmailAccountCreateDto,
  EmailAccountUpdateDto,
  EmailAccountListDto,
  EmailAccountCampaignAssociationDto,
  EmailAccountLookupDto,
  EmailAccountPaginatedListDto,
  EmailAccountResponseDto,
  EmailAccountPaginatedResponseDto,
  BestEmailAccountsForCampaignDto,
  EmailAccountImportResultDto,
} from './dto/email-account.dto';

@ApiTags('emailinfra')
@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @Post('accounts')
  @ApiOperation({ summary: 'Create a new email account' })
  @ApiResponse({ status: 201, type: EmailAccountResponseDto })
  @ApiResponse({ status: 404, description: 'Smartlead inbox not found' })
  @ApiResponse({ status: 500, description: 'Failed to create email account' })
  async createEmailAccount(
    @Body() createDto: EmailAccountCreateDto,
  ): Promise<EmailAccountResponseDto> {
    return this.emailinfraService.createEmailAccount(createDto);
  }

  @Get('accounts/:smartleadInboxId')
  @ApiOperation({ summary: 'Get email account by Smartlead inbox ID' })
  @ApiParam({ name: 'smartleadInboxId', description: 'Smartlead inbox ID' })
  @ApiResponse({ status: 200, type: EmailAccountResponseDto })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  async getEmailAccountById(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ): Promise<EmailAccountResponseDto> {
    const account = await this.emailinfraService.getEmailAccountById(smartleadInboxId);
    if (!account) {
      throw new Error('Email account not found');
    }
    return account;
  }

  @Get('accounts/email/:email')
  @ApiOperation({ summary: 'Get email account by email address' })
  @ApiParam({ name: 'email', description: 'Email address' })
  @ApiResponse({ status: 200, type: EmailAccountResponseDto })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  async getEmailAccountByEmail(
    @Param('email') email: string,
  ): Promise<EmailAccountResponseDto> {
    const account = await this.emailinfraService.getEmailAccountByEmail(email);
    if (!account) {
      throw new Error('Email account not found');
    }
    return account;
  }

  @Get('accounts/client/:smartleadClientId')
  @ApiOperation({ summary: 'Get all email accounts for a Smartlead client' })
  @ApiParam({ name: 'smartleadClientId', description: 'Smartlead client ID' })
  @ApiResponse({ status: 200, type: [EmailAccountResponseDto] })
  async getEmailAccountsByClientId(
    @Param('smartleadClientId') smartleadClientId: string,
  ): Promise<EmailAccountResponseDto[]> {
    return this.emailinfraService.getEmailAccountsByClientId(smartleadClientId);
  }

  @Get('accounts')
  @ApiOperation({ summary: 'List email accounts with pagination' })
  @ApiQuery({ name: 'page', required: false, type: Number, description: 'Page number (default: 1)' })
  @ApiQuery({ name: 'pageSize', required: false, type: Number, description: 'Page size (default: 20, max: 100)' })
  @ApiQuery({ name: 'smartleadClientId', required: false, type: String, description: 'Filter by Smartlead client ID' })
  @ApiResponse({ status: 200, type: EmailAccountPaginatedResponseDto })
  async listEmailAccounts(
    @Query() listDto: EmailAccountPaginatedListDto,
  ): Promise<EmailAccountPaginatedResponseDto> {
    return this.emailinfraService.listEmailAccounts(listDto);
  }

  @Put('accounts/:smartleadInboxId')
  @ApiOperation({ summary: 'Update email account' })
  @ApiParam({ name: 'smartleadInboxId', description: 'Smartlead inbox ID' })
  @ApiResponse({ status: 200, type: EmailAccountResponseDto })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  async updateEmailAccount(
    @Param('smartleadInboxId') smartleadInboxId: string,
    @Body() updateDto: EmailAccountUpdateDto,
  ): Promise<EmailAccountResponseDto> {
    return this.emailinfraService.updateEmailAccount(smartleadInboxId, updateDto);
  }

  @Delete('accounts/:smartleadInboxId')
  @ApiOperation({ summary: 'Delete email account' })
  @ApiParam({ name: 'smartleadInboxId', description: 'Smartlead inbox ID' })
  @ApiResponse({ status: 200, description: 'Email account deleted successfully' })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  @HttpCode(HttpStatus.OK)
  async deleteEmailAccount(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ): Promise<{ message: string }> {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }

  @Post('accounts/associate-campaign')
  @ApiOperation({ summary: 'Associate email accounts with a campaign (idempotent)' })
  @ApiResponse({ status: 200, type: [EmailAccountResponseDto] })
  @ApiResponse({ status: 404, description: 'One or more inbox IDs not found' })
  @ApiResponse({ status: 400, description: 'Invalid request' })
  async associateEmailAccountsWithCampaign(
    @Body() associationDto: EmailAccountCampaignAssociationDto,
  ): Promise<EmailAccountResponseDto[]> {
    return this.emailinfraService.associateEmailAccountsWithCampaign(associationDto);
  }

  @Delete('accounts/:smartleadInboxId/campaigns/:campaignId')
  @ApiOperation({ summary: 'Disassociate email account from a campaign' })
  @ApiParam({ name: 'smartleadInboxId', description: 'Smartlead inbox ID' })
  @ApiParam({ name: 'campaignId', description: 'Campaign ID' })
  @ApiResponse({ status: 200, type: EmailAccountResponseDto })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  async disassociateEmailAccountFromCampaign(
    @Param('smartleadInboxId') smartleadInboxId: string,
    @Param('campaignId') campaignId: string,
  ): Promise<EmailAccountResponseDto> {
    return this.emailinfraService.disassociateEmailAccountFromCampaign(
      smartleadInboxId,
      campaignId,
    );
  }

  @Post('accounts/best-for-campaign')
  @ApiOperation({ summary: 'Get best email accounts for a campaign based on deliverability and load' })
  @ApiResponse({ status: 200, type: BestEmailAccountsForCampaignDto })
  async getBestEmailAccountsForCampaign(
    @Body() listDto: EmailAccountListDto,
  ): Promise<BestEmailAccountsForCampaignDto> {
    return this.emailinfraService.getBestEmailAccountsForCampaign(listDto);
  }

  @Post('accounts/import/:smartleadClientId')
  @ApiOperation({ summary: 'Import email accounts from Smartlead for a client' })
  @ApiParam({ name: 'smartleadClientId', description: 'Smartlead client ID' })
  @ApiResponse({ status: 200, type: EmailAccountImportResultDto })
  @ApiResponse({ status: 500, description: 'Failed to import email accounts' })
  async importEmailAccountsFromSmartlead(
    @Param('smartleadClientId') smartleadClientId: string,
  ): Promise<EmailAccountImportResultDto> {
    return this.emailinfraService.importEmailAccountsFromSmartlead(smartleadClientId);
  }

  @Post('accounts/sync-reputation')
  @ApiOperation({ summary: 'Sync warmup reputation from Smartlead for all accounts or a specific client' })
  @ApiQuery({ name: 'smartleadClientId', required: false, type: String, description: 'Optional Smartlead client ID to filter by' })
  @ApiResponse({ status: 200, type: EmailAccountImportResultDto })
  @ApiResponse({ status: 500, description: 'Failed to sync reputation' })
  async syncWarmupReputation(
    @Query('smartleadClientId') smartleadClientId?: string,
  ): Promise<EmailAccountImportResultDto> {
    return this.emailinfraService.syncWarmupReputation(smartleadClientId);
  }
}

