import { Test, TestingModule } from '@nestjs/testing';
import { EmailinfraService } from './emailinfra.service';
import { DatastoreService } from '../datastore/datastore.service';
import { SmartleadService } from '../smartlead/smartlead.service';
import { StoreDataDto } from '../datastore/dto/store.dto';
import { FindDataResponseDto } from '../datastore/dto/find.dto';
import { documentType } from '../datastore/entites/documentType';
import { EmailAccountEntity, DeliverabilityBand } from './entities/email-account.entity';
import {
  EmailAccountCreateDto,
  EmailAccountUpdateDto,
  EmailAccountListDto,
  EmailAccountCampaignAssociationDto,
  EmailAccountPaginatedListDto,
} from './dto/email-account.dto';
import { NotFoundException, BadRequestException, InternalServerErrorException } from '@nestjs/common';

jest.mock('../datastore/datastore.service');
jest.mock('../smartlead/smartlead.service');

describe('EmailinfraService', () => {
  let service: EmailinfraService;
  let datastoreService: jest.Mocked<DatastoreService>;
  let smartleadService: jest.Mocked<SmartleadService>;

  const mockEmailAccount = {
    smartleadInboxId: 'inbox-123',
    smartleadClientId: 'client-456',
    email: 'test@example.com',
    domain: 'example.com',
    tags: ['tag1', 'tag2'],
    campaignIds: ['campaign-1', 'campaign-2'],
    numberOfCampaignAssociated: 2,
    warmupReputation: 98,
    deliverabilityScore: 98,
    deliverabilityBand: DeliverabilityBand.Medium,
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EmailinfraService,
        {
          provide: DatastoreService,
          useValue: {
            store: jest.fn(),
            getById: jest.fn(),
            getByField: jest.fn(),
            getByPattern: jest.fn(),
            remove: jest.fn(),
          },
        },
        {
          provide: SmartleadService,
          useValue: {},
        },
      ],
    }).compile();

    service = module.get<EmailinfraService>(EmailinfraService);
    datastoreService = module.get(DatastoreService);
    smartleadService = module.get(SmartleadService);

    jest.clearAllMocks();
  });

  describe('DeliverabilityBand mapping', () => {
    it('should map reputation 100 to High', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 100,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.High);
    });

    it('should map reputation 99 to Medium', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 99,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Medium);
    });

    it('should map reputation 98 to Medium', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 98,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Medium);
    });

    it('should map reputation 97 to Low', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 97,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Low);
    });

    it('should map reputation 95 to Low', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 95,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Low);
    });

    it('should map reputation 94 to Burned', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 94,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Burned);
    });

    it('should map reputation 0 to Burned', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 0,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Burned);
    });

    it('should map null reputation to Unknown', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: null,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Unknown);
    });

    it('should map undefined reputation to Unknown', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: undefined,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Unknown);
    });
  });

  describe('EmailAccountEntity', () => {
    it('should extract domain from email', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        email: 'user@domain.com',
      });
      expect(entity.domain).toBe('domain.com');
    });

    it('should handle email without @', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        email: 'invalid-email',
      });
      expect(entity.domain).toBe('');
    });

    it('should track campaign IDs and count', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        campaignIds: ['camp-1'],
      });
      expect(entity.numberOfCampaignAssociated).toBe(1);

      entity.addCampaignId('camp-2');
      expect(entity.campaignIds).toContain('camp-2');
      expect(entity.numberOfCampaignAssociated).toBe(2);

      entity.addCampaignId('camp-1'); // duplicate
      expect(entity.numberOfCampaignAssociated).toBe(2);

      entity.removeCampaignId('camp-1');
      expect(entity.campaignIds).not.toContain('camp-1');
      expect(entity.numberOfCampaignAssociated).toBe(1);
    });

    it('should track tags', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        tags: ['tag1'],
      });
      expect(entity.tags).toContain('tag1');

      entity.addTag('tag2');
      expect(entity.tags).toContain('tag2');

      entity.addTag('tag1'); // duplicate
      expect(entity.tags.filter(t => t === 'tag1').length).toBe(1);

      entity.removeTag('tag1');
      expect(entity.tags).not.toContain('tag1');
    });

    it('should update warmup reputation and band', () => {
      const entity = new EmailAccountEntity({
        ...mockEmailAccount,
        warmupReputation: 90,
      });
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.Burned);

      entity.updateWarmupReputation(100);
      expect(entity.warmupReputation).toBe(100);
      expect(entity.deliverabilityScore).toBe(100);
      expect(entity.deliverabilityBand).toBe(DeliverabilityBand.High);
    });
  });

  describe('createEmailAccount', () => {
    const createDto: EmailAccountCreateDto = {
      smartleadInboxId: 'inbox-new',
      smartleadClientId: 'client-456',
      email: 'new@example.com',
      tags: ['tag1'],
    };

    it('should create new email account', async () => {
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: null }));
      datastoreService.store.mockResolvedValue({} as any);

      const result = await service.createEmailAccount(createDto);

      expect(datastoreService.store).toHaveBeenCalled();
      expect(result.smartleadInboxId).toBe('inbox-new');
      expect(result.email).toBe('new@example.com');
      expect(result.tags).toEqual(['tag1']);
      expect(result.campaignIds).toEqual([]);
      expect(result.numberOfCampaignAssociated).toBe(0);
    });

    it('should throw NotFoundException if Smartlead inbox not found', async () => {
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: null }));

      // Mock the private hydrateFromSmartlead to return null
      const hydrateSpy = jest.spyOn(service as any, 'hydrateFromSmartlead').mockResolvedValue(null);

      await expect(service.createEmailAccount(createDto)).rejects.toThrow(NotFoundException);
      expect(hydrateSpy).toHaveBeenCalledWith('inbox-new', 'client-456');
    });
  });

  describe('getEmailAccountById', () => {
    it('should return email account if found', async () => {
      datastoreService.getById.mockResolvedValue(
        new FindDataResponseDto({ data: mockEmailAccount })
      );

      const result = await service.getEmailAccountById('inbox-123');

      expect(result).toBeDefined();
      expect(result.smartleadInboxId).toBe('inbox-123');
    });

    it('should return null if not found', async () => {
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: null }));

      const result = await service.getEmailAccountById('inbox-999');

      expect(result).toBeNull();
    });
  });

  describe('getEmailAccountByEmail', () => {
    it('should return email account if found', async () => {
      datastoreService.getByField.mockResolvedValue(
        new FindDataResponseDto({ data: [mockEmailAccount] })
      );

      const result = await service.getEmailAccountByEmail('test@example.com');

      expect(result).toBeDefined();
      expect(result.email).toBe('test@example.com');
    });

    it('should return null if not found', async () => {
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: [] }));

      const result = await service.getEmailAccountByEmail('notfound@example.com');

      expect(result).toBeNull();
    });
  });

  describe('getEmailAccountsByClientId', () => {
    it('should return all email accounts for client', async () => {
      datastoreService.getByField.mockResolvedValue(
        new FindDataResponseDto({ data: [mockEmailAccount] })
      );

      const result = await service.getEmailAccountsByClientId('client-456');

      expect(result).toHaveLength(1);
      expect(result[0].smartleadClientId).toBe('client-456');
    });

    it('should return empty array if none found', async () => {
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: [] }));

      const result = await service.getEmailAccountsByClientId('client-999');

      expect(result).toEqual([]);
    });
  });

  describe('listEmailAccounts', () => {
    it('should return paginated results', async () => {
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-1' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-2' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-3' },
      ];
      datastoreService.getByField.mockResolvedValue(
        new FindDataResponseDto({ data: accounts })
      );

      const listDto: EmailAccountPaginatedListDto = {
        page: 1,
        pageSize: 2,
        smartleadClientId: 'client-456',
      };

      const result = await service.listEmailAccounts(listDto);

      expect(result.data).toHaveLength(2);
      expect(result.total).toBe(3);
      expect(result.page).toBe(1);
      expect(result.pageSize).toBe(2);
      expect(result.totalPages).toBe(2);
    });
  });

  describe('updateEmailAccount', () => {
    it('should update tags', async () => {
      datastoreService.getById
        .mockResolvedValueOnce(new FindDataResponseDto({ data: mockEmailAccount }))
        .mockResolvedValueOnce(new FindDataResponseDto({ data: mockEmailAccount }));
      datastoreService.store.mockResolvedValue({} as any);

      const updateDto: EmailAccountUpdateDto = { tags: ['new-tag'] };
      const result = await service.updateEmailAccount('inbox-123', updateDto);

      expect(result.tags).toEqual(['new-tag']);
      expect(datastoreService.store).toHaveBeenCalled();
    });

    it('should throw NotFoundException if account not found', async () => {
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: null }));

      await expect(
        service.updateEmailAccount('inbox-999', { tags: ['tag'] })
      ).rejects.toThrow(NotFoundException);
    });
  });

  describe('deleteEmailAccount', () => {
    it('should delete email account', async () => {
      datastoreService.getById.mockResolvedValue(
        new FindDataResponseDto({ data: mockEmailAccount })
      );
      datastoreService.remove.mockResolvedValue({} as any);

      const result = await service.deleteEmailAccount('inbox-123');

      expect(result.message).toBe('Email account deleted successfully');
      expect(datastoreService.remove).toHaveBeenCalledWith({
        id: 'inbox-123',
        documentType: documentType.EMAIL_ACCOUNT,
      });
    });

    it('should throw NotFoundException if account not found', async () => {
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: null }));

      await expect(service.deleteEmailAccount('inbox-999')).rejects.toThrow(NotFoundException);
    });
  });

  describe('associateEmailAccountsWithCampaign', () => {
    const associationDto: EmailAccountCampaignAssociationDto = {
      emailAccountIds: ['inbox-1', 'inbox-2'],
      campaignId: 'campaign-123',
    };

    it('should associate multiple accounts with campaign idempotently', async () => {
      const account1 = { ...mockEmailAccount, smartleadInboxId: 'inbox-1', campaignIds: [] };
      const account2 = { ...mockEmailAccount, smartleadInboxId: 'inbox-2', campaignIds: ['campaign-123'] };

      datastoreService.getById
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account1 }))
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account2 }));
      datastoreService.store.mockResolvedValue({} as any);

      const result = await service.associateEmailAccountsWithCampaign(associationDto);

      expect(result).toHaveLength(2);
      expect(datastoreService.store).toHaveBeenCalledTimes(2);

      // First account should have campaign added
      const firstStoreCall = datastoreService.store.mock.calls[0][0];
      expect(firstStoreCall.data.campaignIds).toContain('campaign-123');

      // Second account already had campaign, should not duplicate
      const secondStoreCall = datastoreService.store.mock.calls[1][0];
      expect(secondStoreCall.data.campaignIds.filter((c: string) => c === 'campaign-123').length).toBe(1);
    });

    it('should deduplicate repeated inbox IDs in request', async () => {
      const associationWithDuplicates: EmailAccountCampaignAssociationDto = {
        emailAccountIds: ['inbox-1', 'inbox-1', 'inbox-2'],
        campaignId: 'campaign-123',
      };

      const account1 = { ...mockEmailAccount, smartleadInboxId: 'inbox-1', campaignIds: [] };
      const account2 = { ...mockEmailAccount, smartleadInboxId: 'inbox-2', campaignIds: [] };

      datastoreService.getById
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account1 }))
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account2 }));
      datastoreService.store.mockResolvedValue({} as any);

      const result = await service.associateEmailAccountsWithCampaign(associationWithDuplicates);

      expect(result).toHaveLength(2);
      expect(datastoreService.getById).toHaveBeenCalledTimes(2);
      expect(datastoreService.store).toHaveBeenCalledTimes(2);
    });

    it('should throw NotFoundException if any inbox is missing', async () => {
      const account1 = { ...mockEmailAccount, smartleadInboxId: 'inbox-1', campaignIds: [] };

      datastoreService.getById
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account1 }))
        .mockResolvedValueOnce(new FindDataResponseDto({ data: null }));

      await expect(
        service.associateEmailAccountsWithCampaign(associationDto)
      ).rejects.toThrow(NotFoundException);

      // Should not have stored anything
      expect(datastoreService.store).not.toHaveBeenCalled();
    });

    it('should reject entire request if any inbox missing (no partial writes)', async () => {
      const associationDto: EmailAccountCampaignAssociationDto = {
        emailAccountIds: ['inbox-1', 'inbox-2', 'inbox-3'],
        campaignId: 'campaign-123',
      };

      const account1 = { ...mockEmailAccount, smartleadInboxId: 'inbox-1', campaignIds: [] };
      const account2 = { ...mockEmailAccount, smartleadInboxId: 'inbox-2', campaignIds: [] };

      datastoreService.getById
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account1 }))
        .mockResolvedValueOnce(new FindDataResponseDto({ data: account2 }))
        .mockResolvedValueOnce(new FindDataResponseDto({ data: null }));

      await expect(
        service.associateEmailAccountsWithCampaign(associationDto)
      ).rejects.toThrow(NotFoundException);

      // Should not have stored anything
      expect(datastoreService.store).not.toHaveBeenCalled();
    });
  });

  describe('disassociateEmailAccountFromCampaign', () => {
    it('should remove campaign from account', async () => {
      const account = { ...mockEmailAccount, campaignIds: ['campaign-123', 'campaign-456'] };
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: account }));
      datastoreService.store.mockResolvedValue({} as any);

      const result = await service.disassociateEmailAccountFromCampaign('inbox-123', 'campaign-123');

      expect(result.campaignIds).not.toContain('campaign-123');
      expect(result.campaignIds).toContain('campaign-456');
      expect(result.numberOfCampaignAssociated).toBe(1);
    });

    it('should throw NotFoundException if account not found', async () => {
      datastoreService.getById.mockResolvedValue(new FindDataResponseDto({ data: null }));

      await expect(
        service.disassociateEmailAccountFromCampaign('inbox-999', 'campaign-123')
      ).rejects.toThrow(NotFoundException);
    });
  });

  describe('getBestEmailAccountsForCampaign', () => {
    const listDto: EmailAccountListDto = {
      smartleadClientId: 'client-456',
      campaignId: 'campaign-123',
      totalNumberOfEmailsToSend: 500,
      numberOfDaysInCampaign: 10,
      emailsPerInboxPerDay: 20,
    };

    it('should compute required pool size correctly', async () => {
      // 500 / 10 / 20 = 2.5 -> floor = 2
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-1', warmupReputation: 100, deliverabilityScore: 100, numberOfCampaignAssociated: 0, createdAt: '2024-01-01T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-2', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 1, createdAt: '2024-01-02T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-3', warmupReputation: 95, deliverabilityScore: 95, numberOfCampaignAssociated: 0, createdAt: '2024-01-03T00:00:00.000Z' },
      ];
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: accounts }));

      const result = await service.getBestEmailAccountsForCampaign(listDto);

      expect(result.requiredPoolSize).toBe(2);
      expect(result.emailAccounts).toHaveLength(2);
      // Should pick highest reputation first
      expect(result.emailAccounts[0].smartleadInboxId).toBe('inbox-1');
      expect(result.emailAccounts[1].smartleadInboxId).toBe('inbox-2');
    });

    it('should sort by deliverability score descending', async () => {
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-low', warmupReputation: 95, deliverabilityScore: 95, numberOfCampaignAssociated: 0, createdAt: '2024-01-01T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-high', warmupReputation: 100, deliverabilityScore: 100, numberOfCampaignAssociated: 0, createdAt: '2024-01-02T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-med', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-03T00:00:00.000Z' },
      ];
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: accounts }));

      const result = await service.getBestEmailAccountsForCampaign(listDto);

      expect(result.emailAccounts[0].smartleadInboxId).toBe('inbox-high');
      expect(result.emailAccounts[1].smartleadInboxId).toBe('inbox-med');
    });

    it('should sort by campaign count ascending when scores equal', async () => {
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-more-campaigns', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 3, createdAt: '2024-01-01T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-fewer-campaigns', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 1, createdAt: '2024-01-02T00:00:00.000Z' },
      ];
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: accounts }));

      const result = await service.getBestEmailAccountsForCampaign(listDto);

      expect(result.emailAccounts[0].smartleadInboxId).toBe('inbox-fewer-campaigns');
      expect(result.emailAccounts[1].smartleadInboxId).toBe('inbox-more-campaigns');
    });

    it('should sort by domain count ascending when scores and campaigns equal', async () => {
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-same-domain-1', email: 'a@example.com', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-01T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-same-domain-2', email: 'b@example.com', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-02T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-different-domain', email: 'c@other.com', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-03T00:00:00.000Z' },
      ];
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: accounts }));

      const result = await service.getBestEmailAccountsForCampaign(listDto);

      // inbox-different-domain has 0 other inboxes on same domain
      // inbox-same-domain-1 and inbox-same-domain-2 each have 1 other on same domain
      expect(result.emailAccounts[0].smartleadInboxId).toBe('inbox-different-domain');
    });

    it('should sort by creation time oldest first when all else equal', async () => {
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-newer', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-02T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-older', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-01T00:00:00.000Z' },
      ];
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: accounts }));

      const result = await service.getBestEmailAccountsForCampaign(listDto);

      expect(result.emailAccounts[0].smartleadInboxId).toBe('inbox-older');
      expect(result.emailAccounts[1].smartleadInboxId).toBe('inbox-newer');
    });

    it('should handle accounts with null reputation (Unknown band)', async () => {
      const accounts = [
        { ...mockEmailAccount, smartleadInboxId: 'inbox-known', warmupReputation: 98, deliverabilityScore: 98, numberOfCampaignAssociated: 0, createdAt: '2024-01-01T00:00:00.000Z' },
        { ...mockEmailAccount, smartleadInboxId: 'inbox-unknown', warmupReputation: null, deliverabilityScore: null, numberOfCampaignAssociated: 0, createdAt: '2024-01-02T00:00:00.000Z' },
      ];
      datastoreService.getByField.mockResolvedValue(new FindDataResponseDto({ data: accounts }));

      const result = await service.getBestEmailAccountsForCampaign(listDto);

      // Known reputation should rank higher than null
      expect(result.emailAccounts[0].smartleadInboxId).toBe('inbox-known');
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { EmailinfraController } from './emailinfra.controller';
import { EmailinfraService } from './emailinfra.service';
import {
  EmailAccountResponseDto,
  EmailAccountPaginatedResponseDto,
  BestEmailAccountsForCampaignDto,
  EmailAccountImportResultDto,
} from './dto/email-account.dto';
import { DeliverabilityBand } from './entities/email-account.entity';
import { NotFoundException } from '@nestjs/common';

describe('EmailinfraController', () => {
  let controller: EmailinfraController;
  let service: jest.Mocked<EmailinfraService>;

  const mockAccount: EmailAccountResponseDto = {
    smartleadInboxId: 'inbox-123',
    smartleadClientId: 'client-456',
    email: 'test@example.com',
    domain: 'example.com',
    tags: ['tag1'],
    campaignIds: ['campaign-1'],
    numberOfCampaignAssociated: 1,
    warmupReputation: 98,
    deliverabilityScore: 98,
    deliverabilityBand: DeliverabilityBand.Medium,
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [EmailinfraController],
      providers: [
        {
          provide: EmailinfraService,
          useValue: {
            createEmailAccount: jest.fn(),
            getEmailAccountById: jest.fn(),
            getEmailAccountByEmail: jest.fn(),
            getEmailAccountsByClientId: jest.fn(),
            listEmailAccounts: jest.fn(),
            updateEmailAccount: jest.fn(),
            deleteEmailAccount: jest.fn(),
            associateEmailAccountsWithCampaign: jest.fn(),
            disassociateEmailAccountFromCampaign: jest.fn(),
